:root {
  --bg-ticket: #fdf6e3;
  --bg-header: #2c3e2d;
  --bg-spec: #f0e8d0;
  --bg-accent: #7a5c2e;
  --bg-footer: #e8dfc8;
  --color-title: #ffffff;
  --color-studio: #a8c4a2;
  --color-text: #3b2f1e;
  --color-label: #8a7055;
  --color-border: #c8b89a;
  --color-sepia: #8b6348;
  --color-blue: #3a6b8a;
  --color-green: #4a7a5a;
  --color-black: #1a1a1a;
  --status-approved-bg: #d4edda;
  --status-approved-text: #2a6640;
  --status-pending-bg: #fff3cd;
  --status-pending-text: #7a5a00;
  --status-queue-bg: #dce8f5;
  --status-queue-text: #2a4a6a;
}

.press-ticket {
  width: 480px;
  background-color: var(--bg-ticket);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  overflow: hidden;
  font-size: 13px;
  color: var(--color-text);
}

.ticket-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  gap: 12px;
}

.header-left {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.press-badge {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-studio);
  text-transform: uppercase;
}

.press-number {
  font-size: 22px;
  font-weight: 700;
  color: var(--color-title);
  line-height: 1;
}

.header-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.ticket-title {
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--color-title);
  margin: 0;
  line-height: 1;
}

.studio-name {
  font-size: 10px;
  color: var(--color-studio);
  letter-spacing: 0.08em;
  margin: 0;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.date-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-studio);
}

.date-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-title);
}

.ticket-body {
  display: flex;
  flex-direction: row;
  gap: 0;
}

.map-details {
  flex: 1.4;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  border-right: 1px dashed var(--color-border);
}

.detail-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.detail-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--color-label);
  min-width: 74px;
  text-transform: uppercase;
}

.detail-value {
  font-size: 12px;
  font-weight: 500;
  color: var(--color-text);
}

.map-title {
  font-size: 11px;
  font-weight: 700;
  font-style: italic;
  color: var(--color-sepia);
}

.ink-swatches {
  display: flex;
  gap: 5px;
  align-items: center;
}

.swatch {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid var(--color-border);
}

.swatch-black { background-color: var(--color-black); }
.swatch-sepia { background-color: var(--color-sepia); }
.swatch-blue { background-color: var(--color-blue); }
.swatch-green { background-color: var(--color-green); }

.print-specs {
  flex: 1;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.spec-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.spec-block {
  background-color: var(--bg-spec);
  border: 1px solid var(--color-border);
  border-radius: 5px;
  padding: 7px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  margin: 0;
}

.spec-block.accent {
  background-color: var(--bg-accent);
  border-color: var(--bg-accent);
}

.spec-block.accent .spec-value {
  color: var(--color-title);
}

.spec-block.accent .spec-label {
  color: var(--color-studio);
}

.spec-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--color-sepia);
  line-height: 1;
}

.spec-label {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--color-label);
  text-transform: uppercase;
}

.status-row {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}

.status-pill {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  border-radius: 20px;
  padding: 3px 8px;
}

.status-pill.approved {
  background-color: var(--status-approved-bg);
  color: var(--status-approved-text);
}

.status-pill.pending {
  background-color: var(--status-pending-bg);
  color: var(--status-pending-text);
}

.status-pill.queue {
  background-color: var(--status-queue-bg);
  color: var(--status-queue-text);
}

.ticket-footer {
  background-color: var(--bg-footer);
  border-top: 1px dashed var(--color-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  gap: 12px;
}

.footer-label {
  display: block;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-label);
  text-transform: uppercase;
  margin-bottom: 2px;
}

.footer-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text);
}

.ticket-barcode {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 28px;
}

.bar {
  width: 2px;
  height: 100%;
  background-color: var(--color-text);
  border-radius: 1px;
}

.bar.wide {
  width: 4px;
}
